const sharp = require('sharp');
const pptxgen = require('pptxgenjs');

async function createGradientBackground(filename) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="562">
    <defs>
      <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" style="stop-color:#667eea"/>
        <stop offset="100%" style="stop-color:#764ba2"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#g)"/>
  </svg>`;

  await sharp(Buffer.from(svg))
    .png()
    .toFile(filename);

  return filename;
}

async function createPresentation() {
  console.log('Creating gradient background...');
  await createGradientBackground('{{OUTPUT_DIR}}/gradient-bg.png');

  console.log('Initializing presentation...');
  const pptx = new pptxgen();
  pptx.layout = 'LAYOUT_16x9';
  pptx.author = 'CherryStudio';
  pptx.title = 'CherryStudio Product Introduction';

  // Slide 1: Cover - Create manually with gradient
  console.log('Creating slide 1: Cover...');
  const slide1 = pptx.addSlide();
  slide1.background = { path: '{{OUTPUT_DIR}}/gradient-bg.png' };
  slide1.addText('CherryStudio', {
    x: 0, y: 1.5, w: 10, h: 1.5,
    fontSize: 64,
    bold: true,
    color: 'FFFFFF',
    align: 'center',
    valign: 'middle'
  });
  slide1.addText('Your Unified AI Assistant Platform', {
    x: 0, y: 3.2, w: 10, h: 0.6,
    fontSize: 28,
    color: 'FFFFFF',
    align: 'center'
  });
  slide1.addText('Version 1.7.15 | Community & Enterprise Editions', {
    x: 0, y: 4.2, w: 10, h: 0.4,
    fontSize: 18,
    color: 'FFFFFF',
    align: 'center'
  });

  // Slides 2-6: Use html2pptx
  const html2pptx = require('./html2pptx');

  console.log('Creating slide 2: Overview...');
  await html2pptx('{{OUTPUT_DIR}}/slide2-overview.html', pptx);

  console.log('Creating slide 3: Features...');
  await html2pptx('{{OUTPUT_DIR}}/slide3-features.html', pptx);

  console.log('Creating slide 4: Architecture...');
  await html2pptx('{{OUTPUT_DIR}}/slide4-architecture.html', pptx);

  console.log('Creating slide 5: Use Cases...');
  await html2pptx('{{OUTPUT_DIR}}/slide5-usecases.html', pptx);

  console.log('Creating slide 6: Editions...');
  await html2pptx('{{OUTPUT_DIR}}/slide6-editions.html', pptx);

  // Slide 7: Closing - Create manually with gradient
  console.log('Creating slide 7: Closing...');
  const slide7 = pptx.addSlide();
  slide7.background = { path: '{{OUTPUT_DIR}}/gradient-bg.png' };
  slide7.addText('Get Started with CherryStudio', {
    x: 0, y: 1.2, w: 10, h: 1,
    fontSize: 54,
    bold: true,
    color: 'FFFFFF',
    align: 'center'
  });
  slide7.addText('Empower Your Workflow with AI', {
    x: 0, y: 2.3, w: 10, h: 0.5,
    fontSize: 24,
    italic: true,
    color: 'FFFFFF',
    align: 'center'
  });

  // Contact box
  slide7.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 2.5, y: 3.2, w: 5, h: 1.6,
    fill: { color: 'FFFFFF', transparency: 85 },
    line: { type: 'none' },
    rectRadius: 0.15
  });

  slide7.addText([
    { text: 'Website: ', options: { bold: true } },
    { text: 'https://cherry-ai.com' }
  ], {
    x: 2.7, y: 3.4, w: 4.6, h: 0.35,
    fontSize: 16,
    color: 'FFFFFF'
  });

  slide7.addText([
    { text: 'GitHub: ', options: { bold: true } },
    { text: 'github.com/CherryHQ/cherry-studio' }
  ], {
    x: 2.7, y: 3.85, w: 4.6, h: 0.35,
    fontSize: 16,
    color: 'FFFFFF'
  });

  slide7.addText([
    { text: 'Version: ', options: { bold: true } },
    { text: '1.7.15' }
  ], {
    x: 2.7, y: 4.3, w: 4.6, h: 0.35,
    fontSize: 16,
    color: 'FFFFFF'
  });

  // Save presentation
  const outputPath = '{{OUTPUT_DIR}}/CherryStudio-Introduction.pptx';
  console.log(`Saving presentation to ${outputPath}...`);
  await pptx.writeFile({ fileName: outputPath });
  console.log('✓ Presentation created successfully!');
  console.log(`Location: ${outputPath}`);
}

createPresentation().catch(error => {
  console.error('Error creating presentation:', error);
  process.exit(1);
});

