const sharp = require('sharp');
const pptxgen = require('pptxgenjs');

async function createGradientBackground(filename) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="562">
    <defs>
      <linearGradient id="g" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" style="stop-color:#667eea"/>
        <stop offset="100%" style="stop-color:#764ba2"/>
      </linearGradient>
    </defs>
    <rect width="100%" height="100%" fill="url(#g)"/>
  </svg>`;

  await sharp(Buffer.from(svg))
    .png()
    .toFile(filename);

  return filename;
}

async function createPresentation() {
  console.log('Creating gradient background...');
  const bgPath = await createGradientBackground('{{OUTPUT_DIR}}/gradient-bg.png');

  console.log('Initializing presentation...');
  const pptx = new pptxgen();
  pptx.layout = 'LAYOUT_16x9';
  pptx.author = 'CherryStudio';
  pptx.title = 'CherryStudio Product Introduction';

  // Slide 1: Cover
  console.log('Creating slide 1: Cover...');
  const slide1 = pptx.addSlide();
  slide1.background = { path: bgPath };
  slide1.addText('CherryStudio', {
    x: 0, y: 1.5, w: 10, h: 1.2,
    fontSize: 64,
    bold: true,
    color: 'FFFFFF',
    align: 'center'
  });
  slide1.addText('Your Unified AI Assistant Platform', {
    x: 0, y: 3.2, w: 10, h: 0.5,
    fontSize: 28,
    color: 'FFFFFF',
    align: 'center'
  });
  slide1.addText('Version 1.7.15 | Community & Enterprise Editions', {
    x: 0, y: 4.2, w: 10, h: 0.4,
    fontSize: 18,
    color: 'FFFFFF',
    align: 'center'
  });

  // Slide 2: Overview
  console.log('Creating slide 2: Overview...');
  const slide2 = pptx.addSlide();
  slide2.background = { color: 'F8F9FA' };

  slide2.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.5, w: 9, h: 0.8,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide2.addText('Product Overview', {
    x: 0.5, y: 0.5, w: 9, h: 0.8,
    fontSize: 36,
    bold: true,
    color: 'FFFFFF',
    valign: 'middle'
  });

  slide2.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 1.5, w: 9, h: 1.2,
    fill: { color: 'FFFFFF' },
    line: { color: '764ba2', width: 6, pt: 6 },
    rectRadius: 0.12
  });

  slide2.addText('CherryStudio is a powerful desktop AI assistant that provides a unified interface for interacting with multiple LLM providers across all platforms.', {
    x: 0.7, y: 1.65, w: 8.6, h: 0.9,
    fontSize: 16,
    color: '2d3748'
  });

  // Feature boxes
  const features = [
    { emoji: '🤖', title: 'Multi-Provider' },
    { emoji: '📄', title: 'Document AI' },
    { emoji: '🧠', title: 'Knowledge Base' },
    { emoji: '⚡', title: 'Fast & Secure' }
  ];

  features.forEach((feat, i) => {
    const x = 0.5 + (i * 2.3);
    slide2.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x, y: 3, w: 2.1, h: 1.5,
      fill: { color: 'FFFFFF' },
      line: { color: 'E2E8F0', width: 1 },
      rectRadius: 0.1
    });
    slide2.addText(feat.emoji, {
      x, y: 3.15, w: 2.1, h: 0.6,
      fontSize: 40,
      align: 'center'
    });
    slide2.addText(feat.title, {
      x, y: 3.85, w: 2.1, h: 0.5,
      fontSize: 14,
      bold: true,
      color: '667eea',
      align: 'center'
    });
  });

  // Slide 3: Core Features
  console.log('Creating slide 3: Core Features...');
  const slide3 = pptx.addSlide();
  slide3.background = { color: 'F8F9FA' };

  slide3.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide3.addText('Core Features', {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 32,
    bold: true,
    color: 'FFFFFF',
    valign: 'middle'
  });

  const features3 = [
    {
      title: 'Multi-Provider LLM Support',
      items: [
        'OpenAI, Claude, Gemini, Azure, DeepSeek, Mistral',
        'Local models with Ollama and LM Studio',
        'Custom OpenAI-compatible endpoints'
      ]
    },
    {
      title: 'Advanced Document Processing',
      items: [
        'PDF, Word, Excel, Images, EPUB, CSV, XML',
        'Markdown rendering with KaTeX and Mermaid',
        'OCR capabilities for text extraction'
      ]
    },
    {
      title: 'Knowledge Base with RAG',
      items: [
        'Retrieval-Augmented Generation',
        'WebDAV integration for file management',
        'Custom knowledge bases'
      ]
    }
  ];

  let yPos = 1.3;
  features3.forEach(feat => {
    slide3.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x: 0.5, y: yPos, w: 9, h: 1.1,
      fill: { color: 'FFFFFF' },
      line: { color: '764ba2', width: 5, pt: 5 },
      rectRadius: 0.08
    });

    slide3.addText(feat.title, {
      x: 0.7, y: yPos + 0.1, w: 8.6, h: 0.3,
      fontSize: 15,
      bold: true,
      color: '2d3748'
    });

    slide3.addText(feat.items.map(item => `• ${item}`).join('\n'), {
      x: 0.9, y: yPos + 0.45, w: 8.2, h: 0.5,
      fontSize: 12,
      color: '4a5568'
    });

    yPos += 1.2;
  });

  // Slide 4: Technical Architecture
  console.log('Creating slide 4: Technical Architecture...');
  const slide4 = pptx.addSlide();
  slide4.background = { color: 'F8F9FA' };

  slide4.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide4.addText('Technical Architecture', {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 32,
    bold: true,
    color: 'FFFFFF',
    valign: 'middle'
  });

  const archColumns = [
    {
      title: 'Main Process',
      items: ['Node.js Backend', 'MCP Service', 'Knowledge Service', 'Agent System']
    },
    {
      title: 'Renderer Process',
      items: ['React 19.2.0 UI', 'Redux Toolkit', 'TypeScript', 'Dexie Database']
    },
    {
      title: 'Core Services',
      items: ['AI Core Middleware', 'IPC Bridge', 'Storage Service', 'Window Manager']
    }
  ];

  archColumns.forEach((col, i) => {
    const x = 0.5 + (i * 3.1);
    slide4.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x, y: 1.4, w: 2.9, h: 2.3,
      fill: { color: 'FFFFFF' },
      line: { color: 'E2E8F0', width: 2 },
      rectRadius: 0.1
    });

    slide4.addText(col.title, {
      x, y: 1.5, w: 2.9, h: 0.4,
      fontSize: 16,
      bold: true,
      color: '667eea',
      align: 'center'
    });

    slide4.addText(col.items.map(item => `• ${item}`).join('\n'), {
      x: x + 0.2, y: 2, w: 2.5, h: 1.5,
      fontSize: 12,
      color: '4a5568'
    });
  });

  slide4.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 1, y: 4, w: 8, h: 0.7,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide4.addText('Built with Modern Technologies', {
    x: 1, y: 4.05, w: 8, h: 0.3,
    fontSize: 16,
    bold: true,
    color: 'FFFFFF',
    align: 'center'
  });

  slide4.addText('Electron 38.7.0 | React 19 | TypeScript | Redux | pnpm', {
    x: 1, y: 4.4, w: 8, h: 0.25,
    fontSize: 13,
    color: 'FFFFFF',
    align: 'center'
  });

  // Slide 5: Use Cases
  console.log('Creating slide 5: Use Cases...');
  const slide5 = pptx.addSlide();
  slide5.background = { color: 'F8F9FA' };

  slide5.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide5.addText('Use Cases', {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 32,
    bold: true,
    color: 'FFFFFF',
    valign: 'middle'
  });

  const useCases = [
    { emoji: '💼', title: 'Enterprise Teams', desc: 'Centralized management, access control, and knowledge base sharing' },
    { emoji: '👨‍💻', title: 'Developers', desc: 'Code generation, debugging, API testing, and documentation' },
    { emoji: '📚', title: 'Researchers', desc: 'Document analysis, literature review, RAG-powered knowledge' },
    { emoji: '✍️', title: 'Content Creators', desc: 'Writing assistance, translation, content optimization' }
  ];

  useCases.forEach((uc, i) => {
    const x = 0.5 + (i % 2) * 4.8;
    const y = 1.4 + Math.floor(i / 2) * 1.8;

    slide5.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x, y, w: 4.5, h: 1.5,
      fill: { color: 'FFFFFF' },
      line: { color: '764ba2', width: 5, pt: 5 },
      rectRadius: 0.1
    });

    slide5.addText(uc.emoji, {
      x: x + 0.2, y: y + 0.15, w: 0.8, h: 0.6,
      fontSize: 36
    });

    slide5.addText(uc.title, {
      x: x + 1.1, y: y + 0.15, w: 3.2, h: 0.35,
      fontSize: 16,
      bold: true,
      color: '2d3748'
    });

    slide5.addText(uc.desc, {
      x: x + 0.2, y: y + 0.75, w: 4.1, h: 0.6,
      fontSize: 13,
      color: '4a5568'
    });
  });

  // Slide 6: Edition Comparison
  console.log('Creating slide 6: Edition Comparison...');
  const slide6 = pptx.addSlide();
  slide6.background = { color: 'F8F9FA' };

  slide6.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fill: { color: '667eea' },
    line: { type: 'none' },
    rectRadius: 0.1
  });

  slide6.addText('Edition Comparison', {
    x: 0.5, y: 0.4, w: 9, h: 0.7,
    fontSize: 32,
    bold: true,
    color: 'FFFFFF',
    valign: 'middle'
  });

  const editions = [
    {
      name: 'Community',
      color: '16a085',
      features: ['Open-source AGPL-3.0', 'All core features', 'Multi-provider support', 'Local deployment', 'Community support'],
      tag: 'FREE'
    },
    {
      name: 'Enterprise',
      color: '667eea',
      features: ['Centralized management', 'Access control', 'Private deployment', 'Priority support', 'Custom integration'],
      tag: 'COMMERCIAL'
    }
  ];

  editions.forEach((ed, i) => {
    const x = 0.8 + (i * 4.5);

    slide6.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x, y: 1.5, w: 4, h: 3,
      fill: { color: 'FFFFFF' },
      line: { color: 'E2E8F0', width: 2 },
      rectRadius: 0.12
    });

    slide6.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x, y: 1.5, w: 4, h: 0.7,
      fill: { color: ed.color },
      line: { type: 'none' },
      rectRadius: [0.12, 0.12, 0, 0]
    });

    slide6.addText(ed.name, {
      x, y: 1.6, w: 4, h: 0.5,
      fontSize: 24,
      bold: true,
      color: 'FFFFFF',
      align: 'center',
      valign: 'middle'
    });

    slide6.addText(ed.features.map(f => `• ${f}`).join('\n'), {
      x: x + 0.3, y: 2.4, w: 3.4, h: 1.6,
      fontSize: 13,
      color: '4a5568'
    });

    slide6.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
      x: x + 0.7, y: 4.1, w: 2.6, h: 0.35,
      fill: { color: 'F7FAFC' },
      line: { type: 'none' },
      rectRadius: 0.06
    });

    slide6.addText(ed.tag, {
      x: x + 0.7, y: 4.1, w: 2.6, h: 0.35,
      fontSize: 12,
      bold: true,
      color: '667eea',
      align: 'center',
      valign: 'middle'
    });
  });

  // Slide 7: Closing
  console.log('Creating slide 7: Closing...');
  const slide7 = pptx.addSlide();
  slide7.background = { path: bgPath };

  slide7.addText('Get Started with CherryStudio', {
    x: 0, y: 1.2, w: 10, h: 0.8,
    fontSize: 48,
    bold: true,
    color: 'FFFFFF',
    align: 'center'
  });

  slide7.addText('Empower Your Workflow with AI', {
    x: 0, y: 2.2, w: 10, h: 0.5,
    fontSize: 24,
    italic: true,
    color: 'FFFFFF',
    align: 'center'
  });

  slide7.addShape(pptx.shapes.ROUNDED_RECTANGLE, {
    x: 2.5, y: 3.2, w: 5, h: 1.5,
    fill: { color: 'FFFFFF', transparency: 15 },
